// A model of the inventory service for one product, and of the orders that use it.
// The service announces the spec's events after each stock change, where the
// applications call emit.

type tReserveReq = (client: OrderClient, order: string, units: int);

// The atomic design: one request checks stock and reserves it.
event eReserveReq: tReserveReq;
event eReserveResp: (order: string, ok: bool);
event eReleaseReq: (order: string);

// The check-then-reserve design: an order reads the available stock first, then
// commits a reservation the service no longer checks.
event eAvailableReq: (client: OrderClient);
event eAvailableResp: (units: int);
event eCommitReq: tReserveReq;

machine Inventory {
  var stock: int;
  var reservations: map[string, int];

  start state Init {
    entry (units: int) {
      stock = units;
      announce eStocked, (units = units,);
      goto Serving;
    }
  }

  state Serving {
    on eReserveReq do (req: tReserveReq) {
      if (req.units <= stock && !(req.order in reservations)) {
        Reserve(req);
      } else {
        send req.client, eReserveResp, (order = req.order, ok = false);
      }
    }
    on eAvailableReq do (req: (client: OrderClient)) {
      send req.client, eAvailableResp, (units = stock,);
    }
    on eCommitReq do (req: tReserveReq) {
      Reserve(req);
    }
    on eReleaseReq do (req: (order: string)) {
      var units: int;
      if (req.order in reservations) {
        units = reservations[req.order];
        stock = stock + units;
        reservations -= req.order;
        announce eReleased, (order = req.order, units = units);
      }
    }
  }

  fun Reserve(req: tReserveReq) {
    stock = stock - req.units;
    reservations[req.order] = req.units;
    announce eReserved, (order = req.order, units = req.units);
    send req.client, eReserveResp, (order = req.order, ok = true);
  }
}

// One order: reserves its units, then may cancel and release them.
machine OrderClient {
  var inventory: Inventory;
  var order: string;
  var units: int;

  start state Init {
    entry (input: (inventory: Inventory, order: string, units: int, checkFirst: bool)) {
      inventory = input.inventory;
      order = input.order;
      units = input.units;
      if (input.checkFirst) {
        send inventory, eAvailableReq, (client = this,);
        goto Checking;
      }
      send inventory, eReserveReq, (client = this, order = order, units = units);
      goto Reserving;
    }
  }

  state Checking {
    on eAvailableResp do (resp: (units: int)) {
      if (resp.units < units) {
        goto Done;
      }
      send inventory, eCommitReq, (client = this, order = order, units = units);
      goto Reserving;
    }
  }

  state Reserving {
    on eReserveResp do (resp: (order: string, ok: bool)) {
      if (resp.ok && $) {
        send inventory, eReleaseReq, (order = order,);
      }
      goto Done;
    }
  }

  state Done {}
}
// The inventory contract, checked against the P model in this folder and against every example application.
event eStocked: (units: int);
event eReserved: (order: string, units: int);
event eReleased: (order: string, units: int);

// Applications give each product its own monitor through emit's key; the P model has one product.
spec InventoryCorrect observes eStocked, eReserved, eReleased {
  var available: int;
  var reservations: map[string, int];

  start state Unstocked {
    on eStocked do (p: (units: int)) {
      assert p.units >= 0, "negative initial stock";
      available = p.units;
      goto Ready;
    }
    on eReserved do { assert false, "reservation before stock setup"; }
    on eReleased do { assert false, "release before stock setup"; }
  }

  state Ready {
    on eStocked do { assert false, "product stocked twice"; }
    on eReserved do (p: (order: string, units: int)) {
      assert p.units > 0, "reservation must be positive";
      assert !(p.order in reservations), "duplicate reservation";
      available = available - p.units;
      assert available >= 0, "reservation exceeds available stock";
      reservations[p.order] = p.units;
    }
    on eReleased do (p: (order: string, units: int)) {
      assert p.order in reservations, "release without a reservation";
      assert p.units == reservations[p.order], "released quantity differs from reservation";
      available = available + p.units;
      reservations -= p.order;
    }
  }
}
# Checking P models

Run `snappea` in a folder with a `.pproj` file:

```sh
snappea tests                                   # list the test cases
snappea check                                   # check every test case, 10000 schedules each
snappea check tcMyTest -n 1000                  # one test case, 1000 schedules
snappea check 'tcMy*' --time 5m                 # test cases matching a glob, for 5 minutes each
snappea check model.p tcMyTest                  # .p files instead of a .pproj
snappea check tcMyTest --strategy pct:10        # another search strategy
snappea check tcMyTest --exhaustive             # every scheduling and data choice
snappea replay PCheckerOutput/tcMyTest/bug.schedule
```

`snappea check` type-checks the sources itself and reports errors as `p compile` does.
It prints one line per test case and, for a bug, its report and the `snappea replay`
command that reproduces it:

```
$ snappea check -n 300
Checking TwoPhaseCommit: 10 test cases
ok    tcSingleClientNoFailure (300 schedules, 8 workers, 0.06s)
FAIL  tcMultipleClientsWithFailure (bug found after 23 schedules, 8 workers, 0.02s)
      Deadlock detected. Client(6) is waiting to receive an event, but no other controlled tasks are enabled.
      Replay: snappea replay PCheckerOutput/tcMultipleClientsWithFailure/bug.schedule
...
5 of 10 test cases failed in 0.98s, peak memory 18 MB. Output: PCheckerOutput/
```

Each test case's files go to `PCheckerOutput/<test>/`, replacing the previous run's:
`bug.txt` (the buggy schedule's log), `bug.schedule`, `bug.trace.json`, `coverage.txt`,
`summary.txt` and, for scenario monitors, `scenario_coverage.json`. `-v` adds
upstream's progress and statistics. It exits with 0 when no bug is found, 1 when one
is, and 2 on any other error. `snappea <command> --help` lists the options.

`snappea check` explores schedules on one worker thread per CPU core (`-j N` sets the
number). The schedule count is split between the workers, each with its own seed; the
first bug stops them all, and its `bug.schedule` file replays it as usual. The `random`,
`pct`, `fairpct`, `prob` and `pos` strategies use workers; the feedback strategies and
`rl` (which learn from earlier schedules), `--exhaustive` and `--verbose` run one
worker. With more than one worker, a given `--seed` explores different schedules than
upstream, and which bug is reported can vary from run to run; `-j 1` explores exactly
upstream's schedules.

`--exhaustive` explores every scheduling choice and every `$` / `choose` value by
depth-first search, skipping states it has already seen. Its report says whether the
search finished or hit the `--max-steps` bound. Time tracking is not supported in this
mode yet.

Time tracking (`--latency <file>[:<profile>]`, `--timed`) checks timeouts and latency
budgets; see [design/time](../design/time/RetryBudget/README.md).

For installation and a first model, see the [command line guide](https://snappea.dev/docs/cli.html).
For checking application events and logs, see [snappea observe](observe.md).

